        Map<String, Object> noProductId = new HashMap<>(Map.of("quantity", 1));

        assertProblem(createOrder(List.of(noQuantity)), HttpStatus.BAD_REQUEST);
        assertProblem(createOrder(List.of(noProductId)), HttpStatus.BAD_REQUEST);
    }

    @Test
